import { GENERIC } from './generic';

// 100 own ODDO recipes for inspiration: low in calories, rich in protein, few steps, everyday ingredients.
// kcal and protein are worked out from the ingredients' standard values (generic.ts), per one serving.
export type RecipeCat = 'b' | 'm' | 'x' | 's';
type L3 = { de: string; en: string; tr: string };
export type Recipe = { id: string; cat: RecipeCat; mins: number; name: L3; ing: { id: string; g: number }[]; steps: { de: string[]; en: string[]; tr: string[] }; kcal: number; protein: number };

// Ingredients that are not in the everyday food list: [German, English, Turkish, kcal per 100 g, protein per 100 g].
const EXTRA: Record<string, [string, string, string, number, number]> = {
  garlic: ['Knoblauch', 'Garlic', 'Sarımsak', 149, 6.4],
  tomato_paste: ['Tomatenmark', 'Tomato paste', 'Domates salçası', 82, 4.3],
  canned_tomatoes: ['Tomaten aus der Dose', 'Canned tomatoes', 'Konserve domates', 21, 1],
  spices: ['Gewürze nach Geschmack', 'Spices to taste', 'Baharat (isteğe göre)', 0, 0],
  broth: ['Gemüsebrühe', 'Vegetable broth', 'Sebze suyu', 5, 0.5],
  mustard: ['Senf', 'Mustard', 'Hardal', 66, 4],
  soy_sauce: ['Sojasauce', 'Soy sauce', 'Soya sosu', 53, 8],
  cinnamon: ['Zimt', 'Cinnamon', 'Tarçın', 0, 0],
  cocoa: ['Kakaopulver', 'Cocoa powder', 'Kakao', 228, 20],
  pepper_paste: ['Paprikamark', 'Pepper paste', 'Biber salçası', 60, 2.5],
};

const BY_ID = new Map(GENERIC.map(g => [g.id, g]));
const info = (id: string) => {
  const g = BY_ID.get(id);
  if (g) return { name: g.name, kcal100: g.kcal100, protein100: g.protein100 };
  const e = EXTRA[id];
  return { name: { de: e[0], en: e[1], tr: e[2] }, kcal100: e[3], protein100: e[4] };
};
// The ingredient's name without notes in brackets; "gekocht" stays, since the grams are cooked weight.
export const ingName = (id: string, lang: keyof L3) => info(id).name[lang].replace(/\s*\(.*?\)/g, '');

