export const RECIPES: Recipe[] = RAW.map(([id, cat, mins, de, en, tr, ing, sde, sen, str]) => {
  const items = ing.split(' ').map(x => { const [i, g] = x.split(':'); return { id: i, g: Number(g) }; });
  let kcal = 0, protein = 0;
  for (const it of items) { const n = info(it.id); kcal += n.kcal100 * it.g / 100; protein += n.protein100 * it.g / 100; }
  return { id, cat, mins, name: { de, en, tr }, ing: items, steps: { de: sde.split(';'), en: sen.split(';'), tr: str.split(';') }, kcal: Math.round(kcal), protein: Math.round(protein) };
});

export const HIGH_PROTEIN = 25;
